SUBS = {
    "audit-all": None,
    "billing-only": ("dept", "billing"),
    "eu-events": ("region", "eu"),
}

MESSAGES = [
    {"dept": "billing", "region": "us"},
    {"dept": "eng", "region": "eu"},
    {"dept": "billing", "region": "eu"},
]

def matches(filter_spec, attrs):
    if filter_spec is None:
        return True
    key, value = filter_spec
    return key in attrs and attrs[key] == value

def deliver(subs, messages):
    counts = {}
    for name, spec in subs.items():
        counts[name] = sum(1 for m in messages if matches(spec, m))
    return counts

counts = deliver(SUBS, MESSAGES)
for name in sorted(counts):
    print(f"{name}: {counts[name]} messages")
print(f"total deliveries: {sum(counts.values())}")
